'use strict';

// MODULES //

var isnan = require( '@stdlib/math/base/assert/is-nan' );
var float64ToFloat32 = require( '@stdlib/number/float64/base/to-float32' );
var toWord = require( '@stdlib/number/float32/base/to-word' );
var fromWord = require( '@stdlib/number/float32/base/from-word' );
var ABS_MASK = require( '@stdlib/constants/float64/high-word-abs-mask' );
var HIGH_SIGNIFICAND_MASK = require( '@stdlib/constants/float64/high-word-significand-mask' );
var BIAS = require( '@stdlib/constants/float32/exponent-bias' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var kernelLog1p = require( '@stdlib/math/base/special/kernel-log1p' );


// VARIABLES //

var TWO25 = 3.3554432000e+07;   // 0x4c000000
var IVLN2HI = 1.4428710938e+00; /* 0x3fb8b000 */
var IVLN2LO =  -1.7605285393e-04; // 0x3de705fc, 0x2eefa200

// 0x7ff00000 = 2146435072 => 0 11111111111 00000000000000000000 => biased exponent: 2047 = 1023+1023 => 2^1023
var HIGH_MAX_NORMAL_EXP = 0x7f800000|0; // asm type annotation

// 0x00800000 = 1048576 => 0 00000000001 00000000000000000000 => biased exponent: 1 = -1022+1023 => 2^-1022
var HIGH_MIN_NORMAL_EXP = 0x00800000|0; // asm type annotation

// 0x3ff00000 = 1072693248 => 0 01111111111 00000000000000000000 => biased exponent: 1023 = 0+1023 => 2^0 = 1
var HIGH_BIASED_EXP_0 = 0x3f800000|0; // asm type annotation

// High/low words workspace:
var WORDS = [ 0|0, 0|0 ];


// MAIN //

/**
* Evaluates the binary logarithm (base two) for single-precision floating point values.
*
* @param {NonNegativeNumber} x - input value
* @returns {number} function value
*
* @example
* var v = log2f( 4.0 );
* // returns 2.0
*
* @example
* var v = log2f( 8.0 );
* // returns 3.0
*
* @example
* var v = log2f( 0.0 );
* // returns -Infinity
*
* @example
* var v = log2f( Infinity );
* // returns Infinity
*
* @example
* var v = log2f( NaN );
* // returns NaN
*
* @example
* var v = log2f( -4.0 );
* // returns NaN
*/
function log2f( x ) {
	var hfsq;
	var hi;
	var hx;
	var lo;
	var f;
	var R;
	var y;
	var i;
	var k;

	if ( isnan( x ) || x < 0.0 ) {
		return NaN;
	}
	x = float64ToFloat32( x );
	k = 0|0; // asm type annotation
	if ( hx < HIGH_MIN_NORMAL_EXP ) {
		// Case: x < 2**-1022
		if ( hx&ABS_MASK === 0 ) {
			return NINF;
		}
		k -= 25|0; // asm type annotation

		// Subnormal number, scale up x:
		x *= TWO25;
		hx = toWord( x );
	}
	if ( hx >= HIGH_MAX_NORMAL_EXP ) {
		return x + x;
	}
	// Case: log(1) = +0
	if ( hx === HIGH_BIASED_EXP_0 ) {
		return 0.0;
	}
	k += ( (hx>>23) - BIAS )|0; // asm type annotation
	hx &= HIGH_SIGNIFICAND_MASK;
	i = ( ( hx+0x4afb0d ) & HIGH_MIN_NORMAL_EXP )|0; // asm type annotation

	// Normalize x or x/2...
	x = fromWord( hx|(i^HIGH_BIASED_EXP_0) );
	k += (i>>23)|0; // asm type annotation
	y = k;
	f = x - 1.0;
	hfsq = 0.5 * f * f;
	R = kernelLog1p( f );

	/*
	* Notes:
	*
	* We no longer need to avoid falling into the multi-precision
	* calculations due to compiler bugs breaking Dekker's theorem.
	* Keep avoiding this as an optimization.  See e_log2.c for more
	* details (some details are here only because the optimization
	* is not yet available in double precision).
	*
	* Another compiler bug turned up.  With gcc on i386,
	* (ivln2lo + ivln2hi) would be evaluated in float precision
	* despite runtime evaluations using double precision.  So we
	* must cast one of its terms to float_t.  This makes the whole
	* expression have type float_t, so return is forced to waste
	* time clobbering its extra precision.
	*/

	hi = f - hfsq;
	hx = toWord( hi );
	hi = fromWord( hx&ABS_MASK);
	lo = ( f - hi ) - hfsq + R;
	return ( ( lo + hi ) * IVLN2LO ) + ( lo * IVLN2HI ) + ( hi * IVLN2HI ) + y;
}


// EXPORTS //

module.exports = log2f;
